using System.IO;
using System.Reflection;
using System.Text.Json;
using System.Windows;
using System.Windows.Media;
using System.Windows.Media.Imaging;
namespace PID2Process;

internal static class SignalSelfTest
{
    internal static async Task Run(string output,Action<bool,string> check)
    {
        var p=new EngineeringProject();var sensor=new EquipmentItem{Type=EquipmentType.Instrument,Variant="Temperatur",Tag="TT-101",X=.1,Y=.12,Width=.07,Height=.07};var valve=new EquipmentItem{Type=EquipmentType.IsolationValve,Tag="V-101",Variant="2-Wege",X=.7,Y=.55,Width=.1,Height=.1,Actuator=ActuatorType.Manual};var source=new EquipmentItem{Type=EquipmentType.MediaSource,Tag="MED-101",MediumType=MediumType.Liquid};p.Equipment.AddRange([sensor,valve,source]);var pipe=new PipeSegment{Points=[new(.2,.5),new(.5,.5)],StartConnection=new(){EquipmentId=source.Id,Port="Right"}};p.Pipes.Add(pipe);
        var before=JsonSerializer.Serialize(PipeNetwork.Evaluate(p,new()),ProjectServices.JsonOptions);var signal=new SignalLine{Tag="TT-101 regelt V-101",Points=[new(.17,.15),new(.4,.15),new(.75,.15),new(.75,.55)],StartConnection=new(){EquipmentId=sensor.Id,Port="Right"},EndConnection=new(){EquipmentId=valve.Id,Port="Top",Fraction=.3}};p.SignalLines.Add(signal);
        check(before==JsonSerializer.Serialize(PipeNetwork.Evaluate(p,new()),ProjectServices.JsonOptions),"Wirklinie beeinflusst weder Medien noch Rohr-Durchfluss");
        var path=SignalGeometry.Resolve(p,signal);var startX=path[0].X;sensor.X+=.1;check(Math.Abs(SignalGeometry.Resolve(p,signal)[0].X-startX-.1)<1e-10,"Wirklinienanschluss folgt verschobenem Sensor");sensor.X-=.1;
        valve.Width+=.05;check(Math.Abs(SignalGeometry.Resolve(p,signal)[^1].X-(valve.X+valve.Width*.3))<1e-10,"Wirklinie folgt relativer Rahmenposition beim Skalieren");valve.Width-=.05;
        check(SignalGeometry.Markers(path,1400,1050).Count==3,"Klammermarkierung an jedem Wirkliniensegment");
        p.Pdf=new(){FilePath=Path.Combine(output,"model-pages.pdf"),FileName="model-pages.pdf",Sha256=ProjectServices.HashFile(Path.Combine(output,"model-pages.pdf")),PageCount=2};var file=Path.Combine(output,"signal-fixture.pid2process.json");ProjectServices.Save(file,p);var loaded=ProjectServices.Load(file);check(loaded.SignalLines.Count==1&&loaded.SignalLines[0].StartConnection!.EquipmentId==sensor.Id&&loaded.SignalLines[0].Points.Count==4,"Wirklinie und Symbolbindungen im JSON-Roundtrip");check(JsonSerializer.Deserialize<EngineeringProject>("{}",ProjectServices.JsonOptions)!.SignalLines.Count==0,"Alte Projekte ohne Wirklinien weiterhin lesbar");
        var group=OverlaySelection.Group(p,new HashSet<Guid>{sensor.Id,signal.Id});check(OverlaySelection.ExpandGroups(p,[signal.Id],1).Contains(sensor.Id)&&signal.GroupId==group,"Wirklinie unterstützt Gruppen und Mehrfachauswahl");check(OverlaySelection.InRectangle(p,1,new Rect(0,0,1,1)).Contains(signal.Id),"Auswahlrahmen erfasst Wirklinie");OverlaySelection.Apply(p,new HashSet<Guid>{signal.Id},new SelectionPatch(Color:"#AA1122",Function:"Temperaturregelung"));check(signal.Color=="#AA1122"&&signal.Function=="Temperaturregelung","Gemeinsame Eigenschaften bearbeiten Wirklinie");signal.Color="#FF0000";
        var expected=new{project=DocumentExport.Snapshot(p),points=SignalGeometry.Resolve(p,signal),markers=SignalGeometry.Markers(SignalGeometry.Resolve(p,signal),1400,1050)};File.WriteAllText(Path.Combine(output,"signal-scene.json"),JsonSerializer.Serialize(expected,ProjectServices.JsonOptions));
        var detached=DocumentExport.Snapshot(p);var retained=SignalGeometry.Resolve(detached,detached.SignalLines[0]);OverlaySelection.Delete(detached,new HashSet<Guid>{sensor.Id});check(detached.SignalLines[0].StartConnection is null&&detached.SignalLines[0].Points[0].X==retained[0].X,"Sensor entfernen löst Wirklinienbindung geometrieschonend");OverlaySelection.Delete(detached,new HashSet<Guid>{signal.Id});check(detached.SignalLines.Count==0&&detached.Pipes.Count==1,"Wirklinie löschen erhält Rohrleitungen");
        var window=new MainWindow();await window.ImportPdf(p.Pdf.FilePath);var active=window.ActiveProject!;active.Pipes.Add(new(){Points=[new(.2,.3),new(.6,.3)]});object? Invoke(string name,params object?[] args)=>typeof(MainWindow).GetMethod(name,BindingFlags.Instance|BindingFlags.NonPublic)!.Invoke(window,args);Invoke("Signal_Click",window,new RoutedEventArgs());var snap=typeof(MainWindow).GetMethod("Snap",BindingFlags.Instance|BindingFlags.NonPublic)!.Invoke(window,[new PipePoint(.4,.3),null,true]);var snapped=((PipeConnection? Connection,PipePoint Point))snap!;check(snapped.Connection is null,"Wirklinie rastet nicht an vorhandenen Rohrsegmenten ein");
        active.Equipment.Add(valve);var boundary=SignalGeometry.Port(valve,"Top",.3);var hit=typeof(MainWindow).GetMethod("Snap",BindingFlags.Instance|BindingFlags.NonPublic)!.Invoke(window,[boundary,null,true]);var bound=((PipeConnection? Connection,PipePoint Point))hit!;check(bound.Connection?.EquipmentId==valve.Id&&bound.Connection.Port=="Top"&&Math.Abs(bound.Connection.Fraction-.3)<1e-10&&!PipeNetwork.Ports(valve).Contains("Top"),"Wirklinie fängt beliebige Rahmenstelle unabhängig von Rohranschlüssen");
        var sheet=(System.Windows.Controls.Canvas)window.FindName("Sheet");Invoke("AddPipePoint",new Point(.4*sheet.Width,.3*sheet.Height),false);Invoke("AddPipePoint",new Point(.4*sheet.Width,.5*sheet.Height),false);Invoke("AddPipePoint",new Point(.7*sheet.Width,.5*sheet.Height),true);check(active.SignalLines.Count==1&&active.SignalLines[0].Points.Count==3&&active.Pipes.Count==1,"Wirklinienwerkzeug zeichnet mehrere Segmente ohne neues Rohr");Invoke("Signal_Click",window,new RoutedEventArgs());Invoke("AddPipePoint",new Point(.3*sheet.Width,.7*sheet.Height),false);Invoke("CancelPlacement");check(active.SignalLines.Count==1,"Abbruch verwirft nur Wirklinienentwurf");
        window.ClearTestDirtyFlags();var white=BitmapSource.Create(1,1,96,96,PixelFormats.Bgra32,null,new byte[]{255,255,255,255},4);var bitmap=PageVisual.Render(p,1,1400,.75,null,white);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(bitmap));using(var stream=File.Create(Path.Combine(output,"signal-line.png")))png.Save(stream);await ExportService.ExportAsync(p,Path.Combine(output,"signal-review"));await DocumentExport.ExportAsync(p,Path.Combine(output,"signal-line.pdf"),true,0,null);await DocumentExport.ExportAsync(p,Path.Combine(output,"signal-line.jpg"),false,0,null);check(ProjectServices.HashFile(p.Pdf.FilePath)==p.Pdf.Sha256,"Wirklinie in PDF/JPG/Viewer exportiert, Referenz-PDF unverändert");
    }
